	c, p, err := r.Code.Commit(ctx, v, repoID, sha)
	switch {
	case errors.Is(err, repos.ErrNotFound):
		return nil, nil
	case err != nil:
		return nil, fail(ctx, err, "commit", "reading the commit")
	}
